import numpy as np, csv, math, itertools
from scipy.optimize import minimize
rows=list(csv.DictReader(open('/scr/wurgaft/auto-psych/agent_trees/8a52ff3d6e8e6ef7/repo/_runs/cell_1/experiment2/model_loop/responses.csv')))
N=range(1,101)
def isprime(n): return n>1 and all(n%d for d in range(2,int(n**.5)+1))
feats=[{n for n in N if n%2==1},{n for n in N if n%2==0},{n for n in N if isprime(n)},{k*k for k in range(1,11)},{k**3 for k in range(1,5)}]
for b in range(2,11): feats.append({b**k for k in range(1,8) if b**k<=100})
for m in range(3,13): feats.append({n for n in N if n%m==0})
for d in range(10): feats.append({n for n in N if n%10==d})
for d in range(10): feats.append({n for n in N if str(d) in str(n)})
import sys
band=int(sys.argv[1]) if len(sys.argv)>1 else 10
for lo in range(1,101,band): feats.append(set(range(lo,min(lo+band,101))))
feats=[f for f in feats if 0<len(f)<100]
M=np.array([[n in f for n in N] for f in feats],float)
w=np.log(100/M.sum(1))
SIM=(M*w[:,None]).T@M  # 100x100
sets={};S=[];C=[];one=[];y=[]
for r in rows:
    ex=[int(x) for x in r['number_set'].split(',')];t=int(r['target'])
    u=sorted(set(ex))
    S.append(np.mean([SIM[t-1,e-1] for e in ex]))
    if len(u)>1: C.append(np.mean([SIM[a-1,b-1] for a,b in itertools.combinations(u,2)]));one.append(0)
    else: C.append(0);one.append(1)
    y.append(int(r['rating']))
S,C,one,y=map(np.array,(S,C,one,y))
def nll(th,mode):
    a,b,c0,lam=th
    crit=np.where(one==1,c0,lam*C) if mode else np.where(one==1,c0,c0)
    z=a+b*(S-crit); p=1/(1+np.exp(-z)); p=np.clip(p,1e-6,1-1e-6)
    return -np.sum(y*np.log(p)+(1-y)*np.log(1-p))
for mode in (0,1):
    best=min((minimize(nll,x0,args=(mode,),method='Nelder-Mead',options={'maxiter':5000}) for x0 in ([0,.5,3,1],[-1,1,5,1])),key=lambda r:r.fun)
    print(band,mode,best.fun,best.x)
